-- Reconcile legacy profile credits into the immutable transaction ledger without changing balances.
with balances as (select p.id,p.credits,coalesce(sum(case when t.status='completed' and t.type='credit' then t.amount when t.status='completed' and t.type='debit' then -t.amount else 0 end),0)::numeric ledger from public.profiles p left join public.transactions t on t.user_id=p.id group by p.id,p.credits), delta as (select id,credits-ledger d from balances where credits<>ledger) insert into public.transactions(user_id,amount,type,description,status,reference_key) select id,abs(d),case when d>0 then 'credit' else 'debit' end,'Opening balance reconciliation','completed','reconciliation:20261007:'||id from delta where not exists(select 1 from public.transactions t where t.reference_key='reconciliation:20261007:'||delta.id);
